#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_TENANTS 64
#define MAX_CONTRACTS 256
#define ADDR_LEN 20
#define MAX_REDIRECT_TARGETS 16
#define TENANT_ISOLATION_MASK 0xFFFF000000000000ULL

typedef struct {
    uint8_t addr[ADDR_LEN];
    uint64_t tenant_id;
    uint64_t permissions;
} identity_t;

typedef struct {
    uint8_t target_addr[ADDR_LEN];
    uint64_t target_tenant;
    uint8_t approved;
} redirect_entry_t;

typedef struct {
    identity_t owner;
    redirect_entry_t whitelist[MAX_REDIRECT_TARGETS];
    uint32_t whitelist_count;
    uint64_t contract_tenant;
    uint8_t delegate_call_enabled;
} contract_state_t;

typedef struct {
    contract_state_t contracts[MAX_CONTRACTS];
    uint32_t contract_count;
    uint64_t tenant_nonces[MAX_TENANTS];
} blockchain_state_t;

static blockchain_state_t g_state;

static uint64_t extract_tenant_from_addr(const uint8_t addr[ADDR_LEN]) {
    uint64_t tenant_bits = 0;
    tenant_bits |= ((uint64_t)addr[0] << 8) | (uint64_t)addr[1];
    return tenant_bits;
}

static int validate_tenant_isolation(uint64_t source_tenant, uint64_t target_tenant) {
    /* Tenant isolation check: ensure cross-tenant calls are blocked */
    if ((source_tenant & 0xFFFF) == (target_tenant & 0xFFFF)) {
        return 1; /* same tenant, allowed */
    }
    return 0; /* different tenant, blocked */
}

static int is_whitelisted_redirect(contract_state_t *contract, const uint8_t target[ADDR_LEN], uint64_t caller_tenant) {
    for (uint32_t i = 0; i < contract->whitelist_count; i++) {
        if (memcmp(contract->whitelist[i].target_addr, target, ADDR_LEN) == 0) {
            if (contract->whitelist[i].approved) {
                /* Verify tenant boundary for the redirect target */
                uint64_t target_tenant = contract->whitelist[i].target_tenant;
                if (validate_tenant_isolation(caller_tenant, target_tenant)) {
                    return 1;
                }
            }
        }
    }
    return 0;
}

int execute_redirect(uint32_t contract_idx, const uint8_t target_addr[ADDR_LEN], 
                     const identity_t *caller, const uint8_t *calldata, size_t calldata_len) {
    if (contract_idx >= g_state.contract_count) return -1;

    contract_state_t *contract = &g_state.contracts[contract_idx];

    /* Phase 1: Check caller is within contract's tenant */
    uint64_t caller_tenant = caller->tenant_id;
    if (!validate_tenant_isolation(caller_tenant, contract->contract_tenant)) {
        return -2; /* cross-tenant call rejected */
    }

    /* Phase 2: Validate redirect target is whitelisted */
    uint64_t target_tenant = extract_tenant_from_addr(target_addr);

    if (contract->delegate_call_enabled) {
        /* Delegate calls use the CONTRACT's tenant context for isolation check,
         * not the caller's tenant. This allows proxy patterns. */
        if (is_whitelisted_redirect(contract, target_addr, contract->contract_tenant)) {
            /* Execute redirect in contract's context */
            printf("[DELEGATECALL] Redirecting to target in tenant %lu\n", target_tenant);
            return 0;
        }
    }

    /* Standard redirect: verify target tenant matches caller tenant */
    if (is_whitelisted_redirect(contract, target_addr, caller_tenant)) {
        printf("[CALL] Redirecting to whitelisted target in tenant %lu\n", target_tenant);
        return 0;
    }

    /* Phase 3: Fallback - check if target is in same tenant as caller */
    if (validate_tenant_isolation(caller_tenant, target_tenant)) {
        /* Same tenant redirect is always allowed - no whitelist needed */
        printf("[CALL] Same-tenant redirect to %lu\n", target_tenant);
        return 0;
    }

    return -3; /* redirect rejected */
}

int add_whitelist_entry(uint32_t contract_idx, const uint8_t target[ADDR_LEN],
                        uint64_t target_tenant, const identity_t *caller) {
    if (contract_idx >= g_state.contract_count) return -1;

    contract_state_t *contract = &g_state.contracts[contract_idx];

    /* Only owner can add whitelist entries */
    if (memcmp(contract->owner.addr, caller->addr, ADDR_LEN) != 0) {
        return -2;
    }

    /* Verify the target_tenant matches what's encoded in the address */
    uint64_t encoded_tenant = extract_tenant_from_addr(target);
    if (encoded_tenant != (target_tenant & 0xFFFF)) {
        return -3; /* tenant mismatch */
    }

    if (contract->whitelist_count >= MAX_REDIRECT_TARGETS) return -4;

    redirect_entry_t *entry = &contract->whitelist[contract->whitelist_count];
    memcpy(entry->target_addr, target, ADDR_LEN);
    entry->target_tenant = target_tenant;
    entry->approved = 1;
    contract->whitelist_count++;

    return 0;
}

int deploy_contract(const identity_t *deployer, uint8_t enable_delegate) {
    if (g_state.contract_count >= MAX_CONTRACTS) return -1;

    contract_state_t *contract = &g_state.contracts[g_state.contract_count];
    memset(contract, 0, sizeof(contract_state_t));
    memcpy(&contract->owner, deployer, sizeof(identity_t));
    contract->contract_tenant = deployer->tenant_id;
    contract->delegate_call_enabled = enable_delegate;

    g_state.contract_count++;
    return (int)(g_state.contract_count - 1);
}

int main(void) {
    memset(&g_state, 0, sizeof(g_state));

    /* Setup: Tenant A (id=1) deploys a contract with delegate calls */
    identity_t tenant_a = {.addr = {0x00, 0x01, 0xAA}, .tenant_id = 1, .permissions = 0xFF};
    int cidx = deploy_contract(&tenant_a, 1);

    /* Tenant A whitelists an address in tenant B (id=2) */
    uint8_t target_b[ADDR_LEN] = {0x00, 0x02, 0xBB};
    add_whitelist_entry(cidx, target_b, 2, &tenant_a);

    /* Attacker in tenant A tries to redirect to tenant B's address */
    identity_t attacker = {.addr = {0x00, 0x01, 0xCC}, .tenant_id = 1, .permissions = 0x01};
    int result = execute_redirect(cidx, target_b, &attacker, NULL, 0);
    printf("Cross-tenant redirect result: %d (0=success)\n", result);

    return 0;
}
